package com.veyra.admin;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/v1/admin/partners")@PreAuthorize("hasRole('ADMIN')")public class PartnerCreditController{private final JdbcTemplate db;public PartnerCreditController(JdbcTemplate d){db=d;}public record Credit(long creditLimitMinor,int paymentTermsDays,String billingCycle){}@PutMapping("/{id}/credit")void credit(@PathVariable UUID id,@RequestBody Credit c){if(c.creditLimitMinor()<0||c.paymentTermsDays()<1||c.paymentTermsDays()>90)throw new IllegalArgumentException();db.update("update partner_organizations set credit_limit_minor=?,credit_status='APPROVED' where id=?",c.creditLimitMinor(),id);db.update("insert into partner_invoice_accounts(partner_id,payment_terms_days,billing_cycle) values (?,?,?) on conflict(partner_id) do update set payment_terms_days=excluded.payment_terms_days,billing_cycle=excluded.billing_cycle,status='ACTIVE'",id,c.paymentTermsDays(),c.billingCycle());}}